package com.bank.analytics.service;

import java.util.logging.Logger;

// Finds the maximum sum of any contiguous window of exactly k days.
public class DepositWindowAnalyzer {
    private static final Logger log = Logger.getLogger(DepositWindowAnalyzer.class.getName());

    public long maxWindowSum(int[] deposits, int k) {
        if (deposits == null || k <= 0 || k > deposits.length) {
            throw new IllegalArgumentException("Invalid window size k.");
        }
        long windowSum = 0;
        for (int i = 0; i < k; i++) windowSum += deposits[i]; // first window
        long maxSum = windowSum;

        for (int right = k; right < deposits.length; right++) {
            windowSum += deposits[right];        // element entering on the right
            windowSum -= deposits[right - k];    // element leaving on the left
            maxSum = Math.max(maxSum, windowSum);
        }
        final long result = maxSum;
        log.info(() -> "Max sum of any " + k + "-day window = " + result);
        return maxSum;
    }
}
