package com.bank.analytics;

import com.bank.analytics.service.DepositWindowAnalyzer;
import java.util.Arrays;
import java.util.logging.Logger;

public class DepositWindowDemo {
    private static final Logger log = Logger.getLogger(DepositWindowDemo.class.getName());

    public static void main(String[] args) {
        int[] deposits = {3, 1, 4, 1, 5};
        int k = 3;
        log.info(() -> "Deposits: " + Arrays.toString(deposits) + ", k=" + k);

        DepositWindowAnalyzer analyzer = new DepositWindowAnalyzer();
        long best = analyzer.maxWindowSum(deposits, k);

        log.info(() -> "Best " + k + "-day deposit total = " + best);
    }
}
